<script setup>
import SelectField from './SelectField.vue'
import * as executionApi from '../services/executionApi.js'

import { onMounted, onBeforeUnmount, ref } from 'vue'
const props = defineProps({ compact: Boolean, disabled: Boolean })
const policy = ref(null), busy = ref(false), error = ref('')
const levels = [{ id: 'read_only', label: '只查看', detail: '读取已授权资料，回答与搜索。' }, { id: 'assisted', label: '帮我做事', detail: '编辑授权项目；本机命令与应用启动需确认。' }, { id: 'autonomous', label: '自主执行', detail: '在授权范围连续编辑、运行与操作电脑。' }]
let generation = 0, disposed = false
async function load() { const n = ++generation; try { const value = await executionApi.loadExecutionPolicy({}); if (!disposed && n === generation) { policy.value = value; error.value = '' } } catch (cause) { if (!disposed && n === generation) error.value = cause.message } }
async function save(changes) { if (busy.value || !policy.value) return; busy.value = true; error.value = ''; try { policy.value = await executionApi.saveExecutionPolicy({ ...changes, expected_revision: policy.value.revision }, {}); window.dispatchEvent(new Event('mio-execution-policy-changed')) } catch (cause) { if (cause.status === 409) await load(); error.value = cause.status === 409 ? '权限已在其他窗口更新，请重新选择。' : cause.message } finally { busy.value = false } }
async function change(event, key) { const element = event.target, checkbox = element.type === 'checkbox'; await save({[key]:checkbox ? element.checked : element.value}); if (checkbox) element.checked = !!policy.value?.[key]; else element.value = policy.value?.[key] || '' }
function focusRefresh() { if (!busy.value) void load() }
onMounted(() => { void load(); window.addEventListener('focus', focusRefresh); window.addEventListener('mio-execution-policy-changed', focusRefresh) })
onBeforeUnmount(() => { disposed = true; ++generation; window.removeEventListener('focus', focusRefresh); window.removeEventListener('mio-execution-policy-changed', focusRefresh) })
</script>
<template>
  <div :class="['execution-policy', { compact }]" :aria-busy="busy">
    <label v-if="compact" class="permission-select"><span class="sr-only">执行权限</span><SelectField aria-label="执行权限" :value="policy?.mode || ''" :disabled="busy || disabled || !policy" @change="change($event,'mode')"><option v-if="!policy" value="">读取权限…</option><option v-for="level in levels" :key="level.id" :value="level.id">{{ level.label }}</option></SelectField></label>
    <template v-else><h2>执行方式</h2><div class="policy-levels" role="radiogroup" aria-label="执行权限"><button v-for="level in levels" :key="level.id" role="radio" :aria-checked="policy?.mode === level.id" :class="{ active: policy?.mode === level.id }" :disabled="busy || !policy" @click="save({ mode: level.id })"><strong>{{ level.label }}</strong><small>{{ level.detail }}</small></button></div><p class="hint">所有项目共用执行方式。“只查看”优先阻止修改和电脑输入。自主执行不会逐条询问常规命令；本机终端没有系统沙箱。对外提交仍需对应授权，随时可以停止任务。</p>
    <details v-if="policy" class="policy-advanced"><summary>高级：读取范围与终端</summary><label>文件读取范围<SelectField :value="policy.read_scope" :disabled="busy" @change="change($event,'read_scope')"><option value="project">当前项目</option><option value="folders">已授权目录</option><option value="computer">全电脑可读（排除凭据与私人数据）</option></SelectField></label><label>终端运行方式<SelectField :value="policy.terminal_mode" :disabled="busy" @change="change($event,'terminal_mode')"><option value="confirm">每次授权本机命令</option><option value="sandbox" :disabled="!policy.sandbox?.available">隔离环境{{ policy.sandbox?.available ? '' : '（不可用）' }}</option><option value="host">持续授权本机命令</option></SelectField></label><p class="terminal-state">{{ policy.sandbox?.message || '正在读取实际隔离环境状态。' }}</p><p v-if="policy.terminal_mode === 'host'" class="hint">本机终端可访问项目之外的系统资源；目录限制不能隔离任意命令。</p><label class="check"><input type="checkbox" :checked="policy.network_enabled" :disabled="busy" @change="change($event,'network_enabled')" />允许隔离终端联网</label><p class="hint">联网开关只控制隔离终端。本机终端与网页访问由各自授权控制。</p><label class="check"><input type="checkbox" :checked="policy.confirm_project_edits" :disabled="busy" @change="change($event,'confirm_project_edits')" />授权项目内每次编辑仍询问</label></details></template>
    <p v-if="error" class="policy-error" role="alert">{{ error }} <button :disabled="busy" @click="load">重试</button></p>
  </div>
</template>
<style scoped>
.execution-policy{min-width:0}h2{font-size:calc(16px * var(--fs, 1));margin:0 0 14px}.policy-levels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.policy-levels button{display:grid;gap:8px;text-align:left;padding:15px;border:1px solid var(--border);border-radius:10px;background:var(--surface);color:var(--text)}.policy-levels button.active{border-color:var(--accent);background:var(--surface-soft)}small,.hint,.terminal-state{font-size:calc(12px * var(--fs, 1));color:var(--text-muted);line-height:1.7}.hint{margin:12px 0}.policy-advanced{margin-top:18px;font-size:calc(13px * var(--fs, 1))}.policy-advanced summary{cursor:pointer;color:var(--text-muted)}.policy-advanced label{display:grid;gap:8px;margin-top:16px}.policy-advanced .check{display:flex;align-items:center;gap:8px}select{font:inherit;color:inherit;background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:8px;max-width:100%}.compact select{border:0;background:transparent;max-width:118px;font-size:calc(12px * var(--fs, 1));color:var(--text-muted);padding:5px 0}.policy-error{font-size:calc(12px * var(--fs, 1));color:var(--danger);max-width:360px}.compact .policy-error{position:absolute;bottom:100%;background:var(--surface);padding:12px;border:1px solid var(--border);border-radius:8px}.compact{position:relative}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:disabled,select:disabled{opacity:.5}@media(max-width:560px){.policy-levels{grid-template-columns:1fr}}
</style>
